/**
 * Minimal valid JPEG (1×1) for contract tests — no canvas dependency.
 * Public-domain style fixture; not user content.
 */
export const SYNTHETIC_JPEG_BASE64 =
  '';

export function syntheticJpegBytes(): Uint8Array {
  const bin = atob(SYNTHETIC_JPEG_BASE64);
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}
